data.template:
{
  "index": {
    "template": "template.html",
    "header": null,
    "footer": null,
    "query": [
      "query.graphql"
    ],
    "convert_data": "",
    "convert_data_type": "BoaJs"
  },
  "entries": {
    "query.graphql": {
      "type": "GraphGLQuery",
      "data": {
        "query": "query CustomerReturns(
  $storeId: String
  $otherPartyId: String
  $before: String
  $after: String
) {
  invoices(
    storeId: $storeId
    filter: {
      type: { equalTo: CUSTOMER_RETURN }
      otherPartyId: { equalTo: $otherPartyId }
      createdDatetime: { afterOrEqualTo: $after, beforeOrEqualTo: $before }
    }
  ) {
    ... on InvoiceConnector {
      nodes {
        id
        otherPartyName
        lines {
          nodes {
            id
            item {
              id
              code
              name
            }
            batch
            expiryDate
            numberOfPacks
            packSize
            costPricePerPack
          }
        }
      }
    }
  }
}
",
        "variables": null
      }
    },
    "style.css": {
      "type": "Resource",
      "data": "@page {
  margin: 0;
  size: A4 landscape;
}

.paging {
  width: 100%;
}

.container {
  margin: auto;
  padding: 10px;
  font-size: 14px;
  font-family: "Helvetica Neue", "Helvetica", Helvetica, Arial, sans-serif;
  color: #555;
}

.container table {
  width: 100%;
  font-size: inherit;
  font-family: inherit;
  text-align: left;
  margin-top: 10;
  margin-bottom: 15;
  border-collapse: separate;
}

.container table td {
  padding: 10px;
  vertical-align: top;
  border-top: 1px solid rgb(164, 163, 163);
}

.container table tr:last-child td {
  border-bottom: none;
}

.container>table>thead {
  position: -webkit-sticky;
  position: sticky;
  top: 0;
  background-color: #f1f1f1;
}

.container,
body,
.container>table {
  margin-top: 0px;
  padding-top: 0px;
}

.container table tr.heading td {
  font-weight: bold;
  margin-bottom: 15px;
}

.container table td.status span {
  padding: 2px;
  border-radius: 10px;
}
"
    },
    "template.html": {
      "type": "TeraTemplate",
      "data": {
        "output": "Html",
        "template": "<style>
  {% include "style.css" %}
</style>

<div class="container">
  <table>
    <thead>
      <tr class="heading">
        <td>{{t(k="label.customer", f="Customer")}}</td>
        <td>{{t(k="label.code", f="Code")}}</td>
        <td>{{t(k="label.name", f="Name")}}</td>
        <td>{{t(k="label.batch", f="Batch")}}</td>
        <td>{{t(k="label.expiry", f="Expiry")}}</td>
        <td>{{t(k="label.pack-size", f="Pack size")}}</td>
        <td>{{t(k="label.num-packs", f="Number of packs")}}</td>
        <td>{{t(k="label.number-of-units", f="Number of units")}}</td>
        <td>{{t(k="description.pack-cost", f="Cost price per pack")}}</td>
        <td>{{t(k="label.total-cost", f="Total cost")}}</td>
      </tr>
    </thead>
    <tbody>
      {% for line in data.lines %}
      <tr>
        <td>{{line.otherPartyName}}</td>
        <td>{{line.itemCode}}</td>
        <td>{{line.itemName}}</td>
        <td>{{line.batch | default(value='')}}</td>
        <td>
          {%if line.expiryDate %}
          {{line.expiryDate | date(format="%d/%m/%Y")}}
          {% else %}
          {% endif %}
        </td>
        <td style="text-align: right">{{line.packSize}}</td>
        <td style="text-align: right">{{line.numberOfPacks}}</td>
        <td style="text-align: right">{{line.numberOfUnits}}</td>
        <td style="text-align: right">{{line.costPricePerPack}}</td>
        <td style="text-align: right">{{line.totalCost}}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
</div>"
      }
    }
  }
}

