.name\n      }} {% endif %}\n    </span>\n\n    <span id=\"date\">\n      {{ t(k=\"report.printed-date\", f=\"Printed date\") }}: {{ now() |\n      date(format=\"%d/%m/%Y\") }}\n    </span>\n  </div>\n  <div class=\"header-space-between\">\n    <span>\n      {% if data.purchaseOrder.supplier %} {{ data.purchaseOrder.supplier.code }}\n      {% endif %}\n    </span>\n    <span id=\"date\"></span>\n      {{ t(k=\"report.confirmed-date\", f=\"Confirmed date\") }}: \n      {{self::dateOrNA(datetime=data.purchaseOrder.confirmedDatetime)}}\n    </span>\n  </div>\n  <div class=\"header-space-between\">\n    <span>\n      {% if data.purchaseOrder.supplier %} {{ data.purchaseOrder.supplier.address1 }} {%\n      if data.purchaseOrder.supplier.address2 %},\n      {{ data.purchaseOrder.supplier.address2 }} {% endif %} {% endif %}\n    </span>\n    <span>\n    </span>\n  </div>\n</div>\n"
