    "query.graphql": {
      "type": "GraphGLQuery",
      "data": {
        "query": "query PurchaseOrder($dataId: String!, $storeId: String!) {\n  purchaseOrder(storeId: $storeId, id: $dataId) {\n    ... on PurchaseOrderNode {\n      id\n      store {\n        storeName\n        logo\n        name(storeId: $storeId) {\n          address1\n          address2\n          phone\n          email\n        }\n      }\n      supplier {\n        name\n        code\n        address1\n        address2\n      }\n      number\n      lines {\n        nodes {\n          lineNumber\n          item {\n            code\n            name\n            unitName\n          }\n          expectedDeliveryDate\n          requestedNumberOfUnits\n          adjustedNumberOfUnits\n          requestedPackSize\n          pricePerPackAfterDiscount\n          supplierItemCode\n          comment\n        }\n      }\n      foreignExchangeRate\n      status\n      confirmedDatetime\n      orderTotalAfterDiscount\n      currency {\n        code\n      }\n    }\n  }\n  currencies(filter: { isActive: true, isHomeCurrency: true }) {\n    ... on CurrencyConnector {\n      nodes {\n        code\n      }\n    }\n  }\n}\n",
        "variables": null
